import math
n = int(input())
a = list(map(int, input().split()))
x = [1 for x in a if x == 1]
x = len(x)
if x >= 1:
	print(n - x)
	quit()
ans = n
for i in range(n):
	g = a[i]
	for j in range(i, n):
		g = math.gcd(g, a[j])
		if g == 1:
			ans = min(ans, j - i)
if ans == n:
	print(-1)
else:
	print(ans + n - 1)
